user_prompt_template:
LIFE EVENT: {life_event}
ADDITIONAL CONTEXT: {context}

COMPLETED SYSTEM ARCHITECTURE:
{upstream_system_architecture}

DOCUMENT OUTLINE:
{upstream_document_outline}

VALIDATION AUDIT RESULT:
{upstream_validation_audit}

Analyze the above completed life system guide — built specifically for someone navigating '{life_event}' — and produce a comprehensive product launch readiness report. Assess commercial viability and produce a specific, executable go-to-market strategy.

Return ONLY the following JSON object. No prose. No markdown. No code fences.

{{
  "verdict": "launch|polish_first|pivot",
  "verdict_rationale": "One paragraph — specific to this guide's strengths, gaps, and market timing. Not generic.",
  "product_name": "A commercially compelling product name — can differ from the internal system name",
  "product_tagline": "One sentence: the core value proposition for marketing copy",
  "target_buyer": {{
    "primary": "Specific description of who buys this — demographics, life situation, emotional state at purchase",
    "secondary": "Secondary buyer segment if meaningfully different — or null",
    "purchase_trigger": "The specific moment or event that causes them to search for and buy this guide",
    "willingness_to_pay": "Why they would pay — the pain point this resolves or the cost of getting it wrong without the guide"
  }},
  "market_sizing": {{
    "annual_life_event_rate": "Real statistic: how many people per year in the US face this life event",
    "addressable_buyers": "Estimated subset who would search for a guide like this",
    "conversion_assumption": "Realistic % of those who would purchase",
    "market_verdict": "One sentence on whether this market is large enough, timing-sensitive, or niche"
  }},
  "competitive_landscape": [
    {{
      "competitor": "Specific product name or closest category if no direct product exists",
      "their_format": "Book, course, PDF, app, etc.",
      "their_price": "Approximate price point",
      "their_weakness": "The specific gap this guide fills that they do not"
    }}
  ],
  "unique_positioning": "One sentence: what makes this guide the only one of its kind for this life event — must be tied to a specific structural feature of the guide",
  "pricing_model": {{
    "recommended_price": "$XX — exact range, not a spectrum wider than $20",
    "pricing_rationale": "Anchored to specific competitor prices and the guide's scope",
    "format": "PDF download | print-on-demand | digital + print bundle | course | subscription — pick the best fit",
    "launch_price": "Introductory price if discounting at launch — or same as recommended if no discount",
    "upsell": "One adjacent product or service the same buyer would pay for next"
  }},
  "distribution_channels": [
    {{
      "channel": "Specific platform or channel name",
      "why_this_buyer": "Why this channel reaches the primary buyer at the moment of purchase intent",
      "priority": "primary|secondary|experimental",
      "setup_time_days": "Estimated days to go live"
    }}
  ],
  "launch_checklist": [
    {{
      "week": 1,
      "phase": "Pre-launch",
      "tasks": [
        "Specific, executable task — not a category"
      ]
    }}
  ],
  "day_30_marketing_plan": {{
    "hook": "The core marketing message — the pain point or fear this guide resolves, in buyer language",
    "content_angles": [
      "Specific content idea that would resonate with this buyer on this platform"
    ],
    "launch_channels": ["Where to announce: specific platforms or communities"],
    "target_metric": "The one metric to optimize in the first 30 days (units sold, email signups, conversion rate, etc.)"
  }},
  "revenue_estimate_year1": {{
    "low": "$X,XXX",
    "mid": "$XX,XXX",
    "high": "$XXX,XXX",
    "assumptions": "Explicit: X units/month at $Y price = $Z/year — state the numbers"
  }},
  "polish_first_items": [
    "If verdict is polish_first: named, specific things to fix or add before launch. Empty array if verdict is launch or pivot."
  ],
  "key_risks": [
    {{
      "risk": "Specific risk tied to this market or this guide",
      "likelihood": "high|medium|low",
      "mitigation": "Specific action to reduce or eliminate this risk"
    }}
  ]
}}
